Below is a compact, self‑contained example that shows the basic idioms you’ll use with the two most common associative containers in the C++ Standard Library: **`std::map`** (ordered map) and **`std::unordered_map`** (hash‑based map).  

```cpp
// associative_example.cpp
//
// Demonstrates the use of std::map and std::unordered_map.
// Compile with: g++ -std=c++17 associative_example.cpp -o associative_example
// Run: ./associative_example

#include <iostream>
#include <map>
#include <unordered_map>
#include <string>
#include <vector>

using std::cout;
using std::endl;
using std::string;
using std::vector;

// ---------------------------------------------------------------------------
// Helper function to print any key/value map (works for both std::map
// and std::unordered_map because the iterators provide std::pair<const K,V>)
// ---------------------------------------------------------------------------
template <typename Map>
void printMap(const Map& m, const string& title)
{
    cout << title << " (size = " << m.size() << "):\n";
    for (const auto& kv : m)
    {
        cout << "  [" << kv.first << "] = " << kv.second << '\n';
    }
    cout << '\n';
}

// ---------------------------------------------------------------------------
// Main demo
// ---------------------------------------------------------------------------
int main()
{
    /* --------------------------------------------------------------------
       1) std::map – ordered associative array
       -------------------------------------------------------------------- */
    std::map<string, int> ordered_map;

    // Insert values – keys are automatically kept in sorted order
    ordered_map["apple"]  =  3;
    ordered_map["banana"] =  5;
    ordered_map.emplace("cherry", 7);            // emplace is also valid
    ordered_map.insert({"date", 1});              // pair insertion

    // Access – operator[] creates a new entry if key is missing
    cout << "ordered_map['banana'] = " << ordered_map["banana"] << '\n';

    // Look up using find
    auto it = ordered_map.find("banana");
    if (it != ordered_map.end())
        cout << "Found banana with value = " << it->second << '\n';

    // Count – returns 1 if key exists, 0 otherwise
    cout << "ordered_map.count(\"cherry\") = " << ordered_map.count("cherry") << '\n';
    cout << "ordered_map.count(\"fig\")     = " << ordered_map.count("fig")     << '\n';

    // Erase an element
    ordered_map.erase("date");
    printMap(ordered_map, "Ordered map after erasing 'date'");

    /* --------------------------------------------------------------------
       2) std::unordered_map – hash‑based associative array
       -------------------------------------------------------------------- */
    std::unordered_map<string, int> hash_map;

    // Insert values – no ordering guarantee
    hash_map["apple"]  =  3;
    hash_map["banana"] =  5;
    hash_map.emplace("cherry", 7);
    hash_map.insert({"date", 1});

    // The lookup semantics are the same
    cout << "hash_map['banana'] = " << hash_map["banana"] << '\n';

    // Find
    auto it2 = hash_map.find("cherry");
    if (it2 != hash_map.end())
        cout << "Found cherry with value = " << it2->second << '\n';

    // Count
    cout << "hash_map.count(\"date\") = " << hash_map.count("date") << '\n';
    cout << "hash_map.count(\"fig\")  = " << hash_map.count("fig")  << '\n';

    // Erase
    hash_map.erase("date");
    printMap(hash_map, "Unordered map after erasing 'date'");

    /* --------------------------------------------------------------------
       3) A more advanced example – value type is a container
       -------------------------------------------------------------------- */
    std::unordered_map<string, vector<int>> scores;

    // Insert a vector of scores for each student
    scores.emplace("alice", std::initializer_list<int>{85, 90, 78});
    scores.emplace("bob",   std::initializer_list<int>{92, 88, 79});

    // Access the vector and modify it
    scores["alice"].push_back(95);        // add a new score

    // Iterate and compute averages
    cout << "Average scores:\n";
    for (const auto& kv : scores)
    {
        double avg = 0.0;
        for (int s : kv.second) avg += s;
        avg /= kv.second.size();
        cout << "  " << kv.first << ": " << avg << '\n';
    }

    return 0;
}
```

### What the code demonstrates

| Feature | `std::map` | `std::unordered_map` |
|---------|------------|----------------------|
| **Ordering** | Keys are sorted according to `<` (default `std::less`). | No ordering guarantee. |
| **Complexity** | `O(log n)` for insert, find, erase. | Average `O(1)` for insert, find, erase. |
| **Typical use‑cases** | When order matters (e.g., range queries). | When you need fast average‑case access. |
| **Custom key type** | Provide `operator<`. | Provide `std::hash<Key>` and `operator==`. |

Feel free to copy this file, compile, and run it. It will print out the contents of the two maps and show how inserting, accessing, and erasing works in both containers.
